import React, { useEffect, useRef } from 'react';

const BackgroundEffects = () => {
  const canvasRef = useRef(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');

    let animationFrameId;
    let width = (canvas.width = window.innerWidth);
    let height = (canvas.height = window.innerHeight);

    const handleResize = () => {
      width = canvas.width = window.innerWidth;
      height = canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', handleResize);

    // Warm golden particles & GitHub commit nodes
    const particleCount = Math.min(Math.floor(width / 20), 55);
    const particles = Array.from({ length: particleCount }, () => ({
      x: Math.random() * width,
      y: Math.random() * height,
      vx: (Math.random() - 0.5) * 0.35,
      vy: (Math.random() - 0.5) * 0.35,
      radius: Math.random() * 2 + 0.8,
      color: Math.random() > 0.4 ? '#F8F4E1' : (Math.random() > 0.5 ? '#AF8F6F' : '#74512D'),
      alpha: Math.random() * 0.6 + 0.2,
    }));

    const render = () => {
      ctx.clearRect(0, 0, width, height);

      // Draw golden neural & GitHub branch connections
      for (let i = 0; i < particles.length; i++) {
        const p1 = particles[i];
        p1.x += p1.vx;
        p1.y += p1.vy;

        if (p1.x < 0 || p1.x > width) p1.vx *= -1;
        if (p1.y < 0 || p1.y > height) p1.vy *= -1;

        ctx.beginPath();
        ctx.arc(p1.x, p1.y, p1.radius, 0, Math.PI * 2);
        ctx.fillStyle = p1.color;
        ctx.globalAlpha = p1.alpha;
        ctx.fill();

        for (let j = i + 1; j < particles.length; j++) {
          const p2 = particles[j];
          const dx = p1.x - p2.x;
          const dy = p1.y - p2.y;
          const dist = Math.sqrt(dx * dx + dy * dy);

          if (dist < 150) {
            ctx.beginPath();
            ctx.moveTo(p1.x, p1.y);
            ctx.lineTo(p2.x, p2.y);
            ctx.strokeStyle = '#AF8F6F';
            ctx.globalAlpha = (1 - dist / 150) * 0.2;
            ctx.lineWidth = 0.9;
            ctx.stroke();
          }
        }
      }

      animationFrameId = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
    };
  }, []);

  return (
    <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden">
      {/* Golden Particle Canvas Layer */}
      <canvas ref={canvasRef} className="absolute inset-0 opacity-80" />

      {/* Grid Pattern Background */}
      <div className="absolute inset-0 bg-grid-warm opacity-30" />

      {/* Warm Ambient Orbs */}
      <div className="absolute -top-40 left-1/4 w-[600px] h-[600px] bg-bronze-600/20 rounded-full blur-[140px] pointer-events-none animate-pulse-slow" />
      <div className="absolute top-1/3 -right-40 w-[500px] h-[500px] bg-gold-500/10 rounded-full blur-[130px] pointer-events-none animate-float" />
      <div className="absolute -bottom-40 left-1/3 w-[700px] h-[700px] bg-bronze-800/30 rounded-full blur-[160px] pointer-events-none animate-float-reverse" />

      {/* Futuristic Walking Robot Silhouette (Tesla Optimus Style) */}
      <div className="absolute bottom-12 left-0 opacity-15 animate-robot-walk pointer-events-none">
        <svg className="w-16 h-28 text-bronze-100" viewBox="0 0 100 200" fill="currentColor">
          {/* Head & visor */}
          <rect x="35" y="10" width="30" height="25" rx="5" />
          <line x1="40" y1="22" x2="60" y2="22" stroke="#F8F4E1" strokeWidth="4" />
          {/* Neck & Chest */}
          <rect x="42" y="38" width="16" height="10" />
          <path d="M 25 50 L 75 50 L 68 110 L 32 110 Z" />
          {/* Arms */}
          <rect x="12" y="52" width="10" height="50" rx="3" />
          <rect x="78" y="52" width="10" height="50" rx="3" />
          {/* Legs */}
          <rect x="30" y="115" width="16" height="75" rx="4" />
          <rect x="54" y="115" width="16" height="75" rx="4" />
        </svg>
      </div>

      {/* Flying AI Inspection Drone */}
      <div className="absolute top-20 right-1/4 opacity-25 animate-drone-fly pointer-events-none">
        <svg className="w-20 h-10 text-gold-300" viewBox="0 0 100 50" fill="none" stroke="currentColor">
          <circle cx="20" cy="15" r="10" strokeWidth="2" />
          <circle cx="80" cy="15" r="10" strokeWidth="2" />
          <rect x="35" y="20" width="30" height="15" rx="4" fill="currentColor" fillOpacity="0.3" strokeWidth="2" />
          <circle cx="50" cy="27" r="4" fill="#F8F4E1" />
        </svg>
      </div>
    </div>
  );
};

export default BackgroundEffects;
